# Kubernetes Pod CPU Analyzer

This solution parses a list of pod JSON objects, aggregates CPU requests per node (handling the various Kubernetes CPU quantity formats), and flags nodes exceeding a utilization threshold.

```python
"""
pod_cpu_analyzer.py

Analyze Kubernetes pod specs to compute per-node pod counts and CPU request
totals (in millicores), and flag nodes whose requested CPU exceeds a given
percentage of their allocatable CPU.
"""

from __future__ import annotations

from typing import Any, Dict, List, Optional, Union

Number = Union[int, float]


class CPUParseError(ValueError):
    """Raised when a CPU quantity string/value cannot be parsed."""


def parse_cpu_to_millicores(cpu_value: Optional[Union[str, Number]]) -> int:
    """
    Convert a Kubernetes CPU quantity into millicores.

    Accepts:
      - None                  -> 0
      - int/float (cores)     -> value * 1000
      - "250m"                -> 250
      - "1"                   -> 1000
      - "0.5"                 -> 500
      - "1.5"                 -> 1500

    Raises:
      CPUParseError for malformed strings.
    """
    if cpu_value is None:
        return 0

    if isinstance(cpu_value, bool):
        # bool is a subclass of int; guard against accidental True/False input
        raise CPUParseError(f"Invalid CPU value (bool not allowed): {cpu_value!r}")

    if isinstance(cpu_value, (int, float)):
        return int(round(cpu_value * 1000))

    if isinstance(cpu_value, str):
        text = cpu_value.strip()
        if text == "":
            return 0
        try:
            if text.endswith("m"):
                return int(round(float(text[:-1])))
            return int(round(float(text) * 1000))
        except ValueError as exc:
            raise CPUParseError(f"Invalid CPU value: {cpu_value!r}") from exc

    raise CPUParseError(f"Unsupported CPU value type: {type(cpu_value)}")


def get_pod_cpu_millicores(pod: Dict[str, Any]) -> int:
    """
    Sum CPU requests (in millicores) across all containers in a pod.
    Missing resources/requests/cpu fields are treated as 0.
    Malformed CPU values raise CPUParseError (caller may choose to catch).
    """
    spec = pod.get("spec") or {}
    containers = spec.get("containers") or []

    total = 0
    for container in containers:
        resources = container.get("resources") or {}
        requests = resources.get("requests") or {}
        cpu = requests.get("cpu")
        total += parse_cpu_to_millicores(cpu)
    return total


def analyze_pods(
    pods: List[Dict[str, Any]],
    allocatable_cpu: Union[Number, str, Dict[str, Union[Number, str]]],
    threshold: float = 0.9,
    skip_invalid: bool = False,
) -> Dict[str, Dict[str, Any]]:
    """
    Aggregate pod CPU requests per node.

    Args:
        pods: list of pod JSON/dict objects (as returned by the Kubernetes API).
        allocatable_cpu: either a single CPU quantity applied to every node,
            or a dict mapping node name -> CPU quantity (e.g. {"node-1": "4", "node-2": "2000m"}).
        threshold: fraction (0-1) above which a node is flagged as over capacity.
        skip_invalid: if True, pods with unparsable CPU values are skipped
            instead of raising an exception.

    Returns:
        Dict keyed by node name (unscheduled pods grouped under "<unscheduled>"):
        {
            "node-1": {
                "pod_count": int,
                "cpu_millicores": int,
                "allocatable_millicores": Optional[int],
                "usage_ratio": Optional[float],
                "over_threshold": bool,
            },
            ...
        }
    """
    if not isinstance(pods, list):
        raise TypeError("pods must be a list")

    node_data: Dict[str, Dict[str, Any]] = {}

    for pod in pods:
        if not isinstance(pod, dict):
            if skip_invalid:
                continue
            raise TypeError(f"Each pod must be a dict, got {type(pod)}")

        spec = pod.get("spec") or {}
        node_name = spec.get("nodeName") or "<unscheduled>"

        try:
            cpu_m = get_pod_cpu_millicores(pod)
        except CPUParseError:
            if skip_invalid:
                continue
            raise

        entry = node_data.setdefault(
            node_name, {"pod_count": 0, "cpu_millicores": 0}
        )
        entry["pod_count"] += 1
        entry["cpu_millicores"] += cpu_m

    for node_name, data in node_data.items():
        if node_name == "<unscheduled>":
            data["allocatable_millicores"] = None
            data["usage_ratio"] = None
            data["over_threshold"] = False
            continue

        if isinstance(allocatable_cpu, dict):
            alloc_raw = allocatable_cpu.get(node_name)
        else:
            alloc_raw = allocatable_cpu

        if alloc_raw is None:
            data["allocatable_millicores"] = None
            data["usage_ratio"] = None
            data["over_threshold"] = False
            continue

        try:
            alloc_m = parse_cpu_to_millicores(alloc_raw)
        except CPUParseError:
            if skip_invalid:
                data["allocatable_millicores"] = None
                data["usage_ratio"] = None
                data["over_threshold"] = False
                continue
            raise

        data["allocatable_millicores"] = alloc_m
        if alloc_m > 0:
            ratio = data["cpu_millicores"] / alloc_m
        else:
            ratio = float("inf") if data["cpu_millicores"] > 0 else 0.0

        data["usage_ratio"] = ratio
        data["over_threshold"] = ratio > threshold

    return node_data
